proguardAdditions.insert:
-keepclassmembers class * { @android.webkit.JavascriptInterface <methods>; }
-keepattributes JavascriptInterface
-keepattributes *Annotation*
-dontwarn com.razorpay.**
-keep class com.razorpay.** { *; }
-optimizations !method/inlining/*
-keepclasseswithmembers class * { public void onPayment*(...); }

gameActivityImportAdditions.insert:
import com.razorpay.Checkout;
import com.razorpay.PaymentData;
import com.razorpay.PaymentResultWithDataListener;
import org.json.JSONObject;

gameActivityClassAdditions.insert:
/** C++ receives every outcome: code 1000 = success (with ids + signature), otherwise Razorpay's error code. */
public native void nativeRazorpayResult(int code, String orderId, String paymentId, String signature, String message);

/** Opens Razorpay's payment sheet inside the app for an order our server created. */
public void AndroidThunkJava_RazorpayOpen(final String keyId, final String orderId, final int amountPaise,
	final String title, final String description, final String email)
{
	runOnUiThread(new Runnable() {
		@Override
		public void run() {
			try {
				Checkout.preload(getApplicationContext());
				Checkout checkout = new Checkout();
				checkout.setKeyID(keyId);
				JSONObject options = new JSONObject();
				options.put("name", title);
				options.put("description", description);
				options.put("order_id", orderId);
				options.put("currency", "INR");
				options.put("amount", amountPaise);
				options.put("theme.color", "#F08A24");
				JSONObject retry = new JSONObject();
				retry.put("enabled", true);
				retry.put("max_count", 2);
				options.put("retry", retry);
				JSONObject prefill = new JSONObject();
				if (email != null && email.length() > 0) prefill.put("email", email);
				options.put("prefill", prefill);
				checkout.open(GameActivity.this, options);
			} catch (Exception e) {
				nativeRazorpayResult(-1, orderId, "", "", "Could not open the payment sheet: " + e.getMessage());
			}
		}
	});
}

@Override
public void onPaymentSuccess(String razorpayPaymentId, PaymentData data) {
	nativeRazorpayResult(1000, data != null ? data.getOrderId() : "", razorpayPaymentId,
		data != null ? data.getSignature() : "", "");
}

@Override
public void onPaymentError(int code, String response, PaymentData data) {
	nativeRazorpayResult(code, data != null ? data.getOrderId() : "", data != null ? data.getPaymentId() : "", "", response);
}
